\label{prop:relative-global}
The functor $\mathcal D_{S_{\mathbb R}}^{\square}$ is represented
by a complete Noetherian local $W(k)$-algebra $A$, with
\begin{equation}\label{eq:global-frame-parameters}
A\simeq R_{\bar\rho}[[u_1,\ldots,u_{r_1(K)n^2-1}]].
\end{equation}
Moreover, restriction in the frames defines a map $B\to A$ admitting a presentation
\begin{equation}\label{eq:relative-global-presentation}
A\simeq B[[X_1,\ldots,X_t]]/J,\qquad \mu(J)\le o,
\end{equation}
where $\mu(J)$ is the minimal number of generators of $J$, and
\begin{align}
t&=\dim_k\ker(\operatorname{res}^1)
+\sum_{v\in S_{\mathbb R}}h_v^0-1,
\label{eq:relative-global-tangent}\\
o&=\dim_k\operatorname{coker}(\operatorname{res}^1)
+\dim_k\ker(\operatorname{res}^2).
\label{eq:relative-global-obstruction}
\end{align}
In particular, $\dim A\ge\dim B+t-o$.

\label{lem:finite-euler}
		For every finite-dimensional continuous $k$-representation $\rho$ of $G_{K,S}$, we have
		\begin{equation}\label{eq:finite-euler}
			h^0(\rho)-h^1(\rho)+h^2(\rho)
			=\sum_{v\in S_{\mathbb R}}h_v^0(\rho)
			-(r_1(K)+r_2(K))\dim_k\rho.
		\end{equation}

\label{lem:real-surjectivity}
		For every finite-dimensional continuous $k$-representation $\rho$ of $G_{K,S}$,
		the restriction map
		\begin{equation}\label{eq:real-h2-surjection}
			H^2(G_{K,S},\rho)\longrightarrow
			\bigoplus_{v\in S_{\mathbb R}}H^2(G_{v},\rho)
		\end{equation}
		is surjective.

\label{cor:residual-euler}
		With this notation, we have
		\begin{equation}\label{eq:residual-euler}
			\delta(\bar\rho)=h^1-h^2
			=1+n^2r_2(K)+2\sum_{v\in S_{\mathbb R}}s_v(n-s_v).
		\end{equation}

\label{lem:involution}
		For each real prime $v$ of $K$, we have $s_v\le\min(a_v,b_v)$ and
		\begin{equation}\label{eq:invariant-defect}
			\dim_k(\operatorname{ad}\bar\rho)^{c_v=1}-\dim_F(\operatorname{ad} V)^{c_v=1}
			=2(a_v-s_v)(b_v-s_v).
		\end{equation}
		Moreover, the formula for $D_{\mathrm{lift}}(\rho)$ in Theorem~\ref{thm:lift}\textup{(1)} holds, and
		\begin{equation}\label{eq:balanced-gap}
			D(K,n)-D_{\mathrm{lift}}(\rho)
			=\sum_{v\in S_{\mathbb R}}\left\lfloor\frac{(a_v-b_v)^2}{2}\right\rfloor.
		\end{equation}

\label{ques:flatness-nilpotence}
\begin{enumerate}
    \item Does there exist such a $\bar\rho$ for which the unrestricted
    universal deformation ring $R_{\bar\rho}$ is not flat over $W(k)$?
    Equivalently, can $R_{\bar\rho}$ have nonzero $2$-torsion?

    \item Does there exist such a $\bar\rho$ for which
    $\operatorname{Spec} R_{\bar\rho}$ has an irreducible component on which
    $2$ is nilpotent?
\end{enumerate}

If $\bar\rho(c)=I_2$, then $R_{\bar\rho}$ need not be a
	complete intersection, as shown by Theorem~\ref{cor:example}
	with $K=\mathbb Q$; see Remark~\ref{totallyeven}. We do not know whether one should expect $R_{\bar\rho}$ to be flat over $W(k)$ in this case.
